"},{"author":{"account":{"login":"Khuslen122","providerType":"User"},"email":"huslens1027@gmail.com","name":"Khuslen122"},"authoredDate":"2026-05-14T04:41:26Z","committedDate":"2026-05-14T04:41:26Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-09T00:49:02.434Z","repositoryId":1387240452,"sha":"225dc46bb95e1782c4e24f3ca9549fe852c006b4"},{"author":{"account":{"login":"Wlkr123","providerType":"User"},"email":"104069564+Wlkr123@users.noreply.github.com","name":"Tuguldur"},"authoredDate":"2026-05-12T07:35:26Z","committedDate":"2026-05-12T07:35:26Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-09T00:49:02.434Z","repositoryId":1387240452,"sha":"e2f867c1ae500c284801df46fd0569b35ea0162f"},{"author":{"account":{"login":"munkhsaikhan","providerType":"User"},"email":"munkhsaikhan.g@nmma.co","name":"munkhsaikhan"},"authoredDate":"2026-05-06T02:43:58Z","committedDate":"2026-05-06T02:43:58Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-09T00:49:02.434Z","repositoryId":1387240452,"sha":"a9ce8e7c02d4856a560b4daac57c54ea2e314c19"},{"author":{"account":{"login":"munkhsaikhan","providerType":"User"},"email":"munkhsaikhan.g@nmma.co","name":"munkhsaikhan"},"authoredDate":"2026-04-30T19:09:21Z","committedDate":"2026-04-30T19:09:21Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-09T00:49:02.434Z","repositoryId":1387240452,"sha":"bc942c9cfe9137090b104a8afc5a53be274c40ae"},{"author":{"account":{"login":"tsebaa0310","providerType":"User"},"email":"tseba9229@gmail.com","name":"tsebaa0310"},"authoredDate":"2026-04-28T08:39:55Z","committedDate":"2026-04-28T08:39:55Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-09T00:49:02.434Z","repositoryId":1387240452,"sha":"768b3ce7e021c8b7cf6c582c1fc58754b8552338"},{"author":{"account":{"login":"Khuslen122","providerType":"User"},"email":"huslens1027@gmail.com","name":"Khuslen122"},"authoredDate":"2026-04-28T06:36:55Z","committedDate":"2026-04-28T06:36:55Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-09T00:49:02.434Z","repositoryId":1387240452,"sha":"ebc8eb5dbcbaa50cf6a201b3d558f95354e22b57"},{"author":{"account":{"login":"Khuslen122","providerType":"User"},"email":"huslens1027@gmail.com","name":"Khuslen122"},"authoredDate":"2026-04-15T09:55:11Z","committedDate":"2026-04-15T09:55:11Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-09T00:49:02.434Z","repositoryId":1387240452,"sha":"4fd55d3816cde0c57672a8d6a2767bd741d68806"},{"author":{"account":{"login":"Wlkr123","providerType":"User"},"email":"tuguldurch737@gmail.com","name":"Wlkr7575"},"authoredDate":"2026-04-14T07:53:23Z","committedDate":"2026-04-14T07:53:23Z","committer":{"account":{"login":"Wlkr123","providerType":"User"},"email":"tuguldurch737@gmail.com","name":"Wlkr7575"},"observedAt":"2026-10-09T00:49:02.434Z","repositoryId":1387240452,"sha":"f46d484dc35e401b76b9258dcaac038a6f813228"}],"observedAt":"2026-10-09T00:49:02.434Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/amaraa0404org/erxes-plugin-loyalty/commits/25f995195a11bb81067ab7e4b5391afbe06c67e8/comments","commit":{"author":{"date":"2026-09-25T09:59:37Z","email":"amaraa@Erxess-Mac-mini-5.local","name":"Amartuvshin Surenjav"},"comment_count":0,"committer":{"date":"2026-09-25T09:59:37Z","email":"amaraa@Erxess-Mac-mini-5.local","name":"Amartuvshin Surenjav"},"message":"docs: add extraction README and gitignore","tree":{"sha":"e95dd4c04fdc00dcbbd7ec6a792cd106520f4e27","url":"htt